    if (h) {
      union mt_ptr ptr;
      mrb_sym ret = mt_get(mrb, h, mid, &ptr);
      if (ret) {
        if (ptr.proc == 0) break;
        *cp = c;
        if (ret & MT_FUNC_P) {
          MRB_METHOD_FROM_FUNC(m, ptr.func);
        }
        else {
          MRB_METHOD_FROM_PROC(m, ptr.proc);
        }
        if (ret & MT_NOARG_P) {
          MRB_METHOD_NOARG_SET(m);
        }
#ifndef MRB_NO_METHOD_CACHE
        mc->c = oc;
        mc->c0 = c;
        mc->mid = mid;
        mc->m = m;
